import{_ as p,H as a,f as t,i as A}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"结束语 | 融入AI技术革命浪潮，实现人生百倍提升","description":"","frontmatter":{},"headers":[{"level":3,"title":"我想到的第一个词，叫做“时代”。","slug":"我想到的第一个词-叫做-时代-。","link":"#我想到的第一个词-叫做-时代-。","children":[]},{"level":3,"title":"也就是我想到的第二个词，叫做“生意”。","slug":"也就是我想到的第二个词-叫做-生意-。","link":"#也就是我想到的第二个词-叫做-生意-。","children":[]},{"level":3,"title":"这正是我思考的第三个词，叫做“个体”。","slug":"这正是我思考的第三个词-叫做-个体-。","link":"#这正是我思考的第三个词-叫做-个体-。","children":[]}],"relativePath":"AI大模型项目落地实战/结束语｜融入AI技术革命浪潮，实现人生百倍提升.md","filePath":"AI大模型项目落地实战/结束语｜融入AI技术革命浪潮，实现人生百倍提升.md","lastUpdated":1795453306000}'),i={name:"AI大模型项目落地实战/结束语｜融入AI技术革命浪潮，实现人生百倍提升.md"};function n(r,e,l,s,I,o){return a(),t("div",null,[...e[0]||(e[0]=[A('<h1 id="结束语-融入ai技术革命浪潮-实现人生百倍提升" tabindex="-1">结束语 | 融入AI技术革命浪潮，实现人生百倍提升 <a class="header-anchor" href="#结束语-融入ai技术革命浪潮-实现人生百倍提升" aria-label="Permalink to &quot;结束语 | 融入AI技术革命浪潮，实现人生百倍提升&quot;">​</a></h1><p>你好，我是金伟。</p><p>我自己也没有想到，做一门课的挑战居然这么大，特别是写这篇结束语，居然让我反反复复在脑子里思索了 2 周时间，也写不下第一句话。此时此刻，已经是凌晨 3 点钟，我正独自在北京郊区的工作室里，苦苦思考着这样一个问题：如果我有机会对因这门课而来的朋友们聊几句技术之外的话，应该聊什么呢？</p><h3 id="我想到的第一个词-叫做-时代-。" tabindex="-1">我想到的第一个词，叫做“时代”。 <a class="header-anchor" href="#我想到的第一个词-叫做-时代-。" aria-label="Permalink to &quot;我想到的第一个词，叫做“时代”。&quot;">​</a></h3><p>大概在 20 年前，那还是我的学生时代，印象最深的是一次计算机实验，当时也是整整熬了一个通宵，我们几个系里的“技术高手”组成的团队，从 CPU 微指令设计开始，用手工插线的方式完整地搭建了一台微型的计算机，并且用汇编语言在这台自己的计算机上实现了一个跑马灯的效果。</p><p>你可能难以想象这样的场景：为了完成这个艰巨的实验，当时我们用掉了整个实验室的电路连接线，并且每一根线都可能需要单独调试。不过，当最终跑通程序的那一刻，对于“计算机”“技术”和“团队”到底是什么，我第一次有了深刻的感悟。我想同样作为工程师的你，一定可以理解我当时的心情吧。可以说，实现了一项技术的成就感是工程师最大的幸福来源。</p><p>而就在我们做这个实验的同时，我们其中的一位“高手”提了一个震惊我的问题，他说, “你们觉得什么时候 AI 可以完全替代我们这样的程序员，实现自主编程呢？”，你要知道，这可是在20 年前，很多现在流行的编程语言当时才刚刚被发明出来。</p><p>一转眼，现在 “AI 时代”到来了，AI 自我编程也不是什么难事了，而这位提出问题的同学，已经是一个独角兽 AI 公司的 CTO。另一位参与实验的同学，则早已到国外最顶级公司，成为了技术专家，也实现了阶层的跨域。而同样作为“技术牛人”的我，又有什么故事呢?</p><p>我在 2005 年加入了当时最大的互联网公司，新浪网。我是国内第一个修改 MySQL 源代码的人。我们团队做了国内第一个云计算平台。离开新浪网之后，就是创业接着创业，做过国内最大的企业家社交网络，做过国内最大的小学数学学习平台，双减之后，成为“超级个体”。而此刻，我正在为这门大模型课程加班中。</p><p>大多数 20 年前的技术同事，现在都已经是独角兽公司的 CTO，他们会这样评价我，说“别人都是成功接着成功，你怎么总是失败连着失败呢?”。确实，在过去 20 年这样的技术大时代面前，没能抓住成功的机遇，真的是非常遗憾的事情。</p><p>然而实际情况则比“失败”还要严重，诡异的是，作为一个有丰富经验的工程师，往往面临比失败还要可怕的事情，叫做“失业”。实际情况就是，随着年龄增大，“失业”危机会天天围绕着你。这也正是我在 “AI 时代”到来的时候，疯狂地开启 AI 学习模式，疯狂地找各种 AI 项目开发的原因。往好了说叫“创新创业”，底层逻辑则仅仅是为了“防止失业”。</p><p>有趣的是，我发现很多年纪相仿的工程师，不是在做 AI 项目就是在往 AI 转型的路上。反过来想，这也正是这个 AI 大时代给我们这些 IT 老人的重启机会吧。回顾 20 年的职业生涯的教训，再展望未来 20 年的 AI 时代，我还想分享另外一点个人的小感悟。</p><h3 id="也就是我想到的第二个词-叫做-生意-。" tabindex="-1">也就是我想到的第二个词，叫做“生意”。 <a class="header-anchor" href="#也就是我想到的第二个词-叫做-生意-。" aria-label="Permalink to &quot;也就是我想到的第二个词，叫做“生意”。&quot;">​</a></h3><p>作为一个“高贵”的工程师, 我一开始是非常讨厌“生意”这个词的。在我们的思想里，没有生意，只有创业、融资、上市。在以前，我跟生意的唯一关系，就是我有一堆做生意成功的亲戚。在我这样一个“工程师”眼里，这些人做生意赚了大钱全是运气，没有什么技术含量。</p><p>但真的是这样吗？直到 6 年前，我彻底离开了“打工”这个状态，自己在市场上摸索，才慢慢理解了什么是“生意”。</p><p>你可能会奇怪，我已经做到了独角兽公司的 CTO 级别，难道还不会做生意吗？现实情况就是，当我离开工作岗位，投身到市场上之后，我的商业能力就是零。现在差不多 6 年过去了，我还是不敢说自己具备了做生意的能力，更谈不上创业能力了。唯一值得分享的是，6 年的市场历练，我还活着，没有回到打工的状态。</p><p>你可能都无法想象，我的第一笔生意是怎么做成的？赚了多少钱？</p><p>那已经是 6 年前了，在辞职后，经过半年的摸索，我开发的一个系统才迎来了第一个付费用户。我现在还清楚地记得，当时的付费金额是 6.6 元，还是因为我帮客户解决了一个问题，他给我的红包钱。说实话，第一次用自己做的产品获得价值回报，和我 20 年前第一次做计算机大实验的兴奋程度是相当的。我赚到这 6.6 之后，第一时间就去超市全买成了糖果，分享给家人了。</p><p>一个工程师学做生意, 往往就是这么难，因为“工程师”和“生意人”正好是人的两个极端状态。不过，20 年前，我立志用 10 年时间做到架构师级别，我做到了。而 5、6 年前我离开打工状态时，也做好了 10 年才能成为生意人的准备，现在我相信自己一定可以做到。</p><p>关于“生意”的另一个感悟，正好和我最近合作的一位 CTO 级别的朋友不谋而合。他跟我说，“特别后悔自己在做 CTO 的时候，一心扑在公司的事业上，完全没考虑有一天会失业，要是早知道会中年失业，应该在打工的时候就开始创业”。这位朋友的心态已经彻底转变，现在即使去打工，也会同时考虑如何学习做生意。这是我看到的最鲜活的例子了，我想对所有工程师都应该有启发。</p><p>你知道吗？就我刚才说到的那个系统已经持续经营了 6 年，而且还能运行至少 20 年，现在已经有几万付费用户了。我想这就算一个小小的“生意”了。</p><p>而说回到我们的大模型开发课程呢？实际上我一开始就知道它是不完美的，我最开始并不是什么 AI 专家，也在摸爬滚打中学习，而且 AI 领域变化太快了，今天的知识明天就过期了，那怎么办呢?</p><p>我把这门课程，甚至每篇文章，都当成一个要持续做的生意在经营，这就是为什么我会花几天几夜去琢磨一篇文章的文字。我也并没有把自己当做什么老师，我想如果可以借着这门课程找到几千个志同道合的朋友一起进步，就已经非常幸福了。</p><p>那在接下来的 AI 大时代，真的每个人都可以成功吗?</p><h3 id="这正是我思考的第三个词-叫做-个体-。" tabindex="-1">这正是我思考的第三个词，叫做“个体”。 <a class="header-anchor" href="#这正是我思考的第三个词-叫做-个体-。" aria-label="Permalink to &quot;这正是我思考的第三个词，叫做“个体”。&quot;">​</a></h3><p>就在我做这门课程的同时，发生了几件小事，其中一件是我开启了一个新的 AI 项目，而这个项目里我在和一个 00 后的算法工程师合作，在他身上我发现了年轻工程师的优点：个性、独立、创新，都非常值得我学习。而另一件事更有意思，是一位之前认识的 95 后工程师，买了这个大模型开发课之后联系我，我发现他已经每天在网络上分享自己对 AI 的认知了。</p><p>现在的主力工程师已经是 95 和 00 后了，我想你也很可能是其中的一员，说实话，你这么年轻就赶上这样一个 AI 个体爆发的时代，我这样一个 IT 老人真的是“羡慕嫉妒恨”啊！我花了 20年才敢出来写文章分享，而你可能天生就具备输出基因，这是多好的先天条件啊！</p><p>你可能会想，不是说 AI 会导致更多的内卷和失业吗？那不应该是巨头垄断算力吗？个体怎么会有机会呢?</p><p>我的想法正好相反，正因为 AI 释放了大量的人类算力，并且个人极容易获得 AI 能力，一个传统的观念将被颠覆——以前的观点是：想法不重要，执行才重要。在 AI 时代，一个想法真的太容易用 AI 快速测试了，你只需要写一个智能体 Agent，当天就可以收到用户的反馈。</p><p>为什么当 AI 时代到来的时候，我反而更加兴奋了？因为我一直以来的观点就是个体会崛起，而公司这种体制将走向终结。</p><p>在 AI 时代，一个人因为一个想法而实现原来需要 100 个人或 100 年才能实现的目标是很可能的。</p><p>说回到这门课程的起点，做课程实际上并不是我一开始的计划，而是我在和一个 AI 专家讨论技术难题的过程中迸发的想法，我在想“既然 AI 专家没时间写一门实战课程，为什么我不能做呢？”就这样一个简单的念头，产生了你我在此相会的因缘。</p><p>你看，这正是 AI 时代最妙的地方。</p><p>作为结束语的最后一句，我想说，年轻的你才是 AI 时代最大的主角，千万不要把我这个 IT 老人当成老师，而要把我和 AI 都当做你工具箱里的一个工具，不管打工还是创业，一定可以实现你的人生百倍提升。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E9%A1%B9%E7%9B%AE%E8%90%BD%E5%9C%B0%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p>',35)])])}const E=p(i,[["render",n]]);export{h as __pageData,E as default};
